              "id": "company_team",
              "label": "Company brain shared with a team (prints where it lives; creates nothing)",
              "argv": [
                "gbrain",
                "setup",
                "claude-code",
                "--shape",
                "company",
                "--team"
              ]
            },
            {
              "id": "none",
              "label": "No starter pages (memory works as it is)"
            }
          ],
          "default": "none",
          "default_reason": "Nothing is written until the user picks; memory already works without it."
        }
      ],
      "contract_version": 1
    }
  ]
}

